// julia_bridge.js — optional build-time JSON loader, JS stays the runtime!
// Each app fetches its precomputed file generated by julia/scripts/build.jl!

export async function loadJuliaArtifact(path) {
  try {
    const res = await fetch(path);
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

